/** Original score + water/party feedback. No downloads, samples, or autoplay. */
const clamp01 = v => Math.max(0, Math.min(1, Number.isFinite(+v) ? +v : 0));
const isLive = phase => phase === 'playing' || phase === 'countdown';

export class GameAudio {
  constructor({ musicDataUri = BUILTIN_MUSIC_DATA_URI, contextFactory, documentRef = globalThis.document } = {}) {
    this.enabled = true;
    this.musicVolume = .52;
    this.sfxVolume = .78;
    this.musicDataUri = musicDataUri;
    this._contextFactory = contextFactory || (() => {
      const AudioContext = globalThis.AudioContext || globalThis.webkitAudioContext;
      return AudioContext ? new AudioContext() : null;
    });
    this._document = documentRef;
    this._backgrounded = !!documentRef?.hidden;
    this._foregroundGestureRequired = false;
    this._unlocked = false;
    this._disposed = false;
    this._manualPaused = false;
    this._manualStopped = false;
    this._streams = new Map();
    this._voices = new Set();
    this._musicOffset = 0;
    this._lastPhase = 'ready';
    this._lastState = { phase: 'ready', actors: [] };
    this._lastEventSeq = 0;
    this._lastRoundId = null;
    this._lastResultAt = -100;
    this._lastDryAt = -100;
    this._lastHitAt = -100;
    this._visibility = () => {
      this._backgrounded = !!this._document?.hidden;
      if (this._backgrounded) {
        this._foregroundGestureRequired = true;
        this._haltAll();
      }
      // A returning page needs a real gesture; update cannot silently restart it.
    };
    documentRef?.addEventListener?.('visibilitychange', this._visibility);
  }

  async unlock() {
    if (this._disposed || this._backgrounded) return false;
    this._manualStopped = false;
    this._foregroundGestureRequired = false;
    if (this._lastState.phase !== 'paused') this._manualPaused = false;
    if (this._unlockPending) return this._unlockPending;
    this._unlockPending = this._unlock().finally(() => { this._unlockPending = null; });
    return this._unlockPending;
  }

  async _unlock() {
    try {
      if (!this.context) {
        const ctx = this._contextFactory();
        if (!ctx) return false;
        this.context = ctx;
        this._master = ctx.createGain();
        this._musicBus = ctx.createGain();
        this._sfxBus = ctx.createGain();
        this._musicBus.connect(this._master);
        this._sfxBus.connect(this._master);
        this._master.connect(ctx.destination);
        this._master.gain.value = this.enabled ? 1 : 0;
        this._musicBus.gain.value = this.musicVolume * .34;
        this._sfxBus.gain.value = this.sfxVolume;
        this._noiseBuffer = this._createWaterNoise();
      }
      if (this.context.state === 'suspended') await this.context.resume();
      if (this._disposed) return false;
      this._unlocked = true;
      if (!this._musicBuffer && this.musicDataUri && !this._decodeFailed) {
        try {
          const encoded = this.musicDataUri.split(',')[1] || '';
          const bytes = Uint8Array.from(globalThis.atob(encoded), c => c.charCodeAt(0));
          this._musicBuffer = await this.context.decodeAudioData(bytes.buffer);
        } catch (error) { this._decodeFailed = true; this._lastError = String(error?.message || 'Music decode failed'); }
      }
      if (!this._disposed) this._sync();
      return !this._disposed && !this._decodeFailed;
    } catch (error) {
      // Gameplay remains usable if a browser or device has no audio output.
      this._lastError = String(error?.message || 'Audio output unavailable');
      return false;
    }
  }

  setEnabled(enabled) {
    this.enabled = !!enabled;
    if (this.context) this._gain(this._master.gain, this.enabled ? 1 : 0, 0);
    if (!this.enabled) this._haltAll();
    else this._sync();
  }

  setMusicVolume(value) {
    this.musicVolume = clamp01(value);
    if (this.context) this._gain(this._musicBus.gain, this._musicLevel(), 0);
  }

  setSfxVolume(value) {
    this.sfxVolume = clamp01(value);
    if (this.context) this._gain(this._sfxBus.gain, this.sfxVolume, 0);
  }

  update(state, dt = 0) {
    if (!state || this._disposed) return;
    const phase = state.phase || 'ready';
    if (state.roundId != null && state.roundId !== this._lastRoundId) {
      this._lastRoundId = state.roundId;
      this._lastEventSeq = 0;
      this._lastResultAt = -100;
    }
    if (phase !== this._lastPhase && (isLive(phase) || phase === 'ready')) {
      this._manualPaused = false;
      if (phase === 'countdown') this._lastResultAt = -100;
    }
    this._lastState = state;
    this._lastPhase = phase;
    this._sync();
  }

  _canPlay() {
    return !this._disposed && this.enabled && this._unlocked && !!this.context &&
      this.context.state === 'running' && !this._backgrounded && !this._document?.hidden &&
      !this._foregroundGestureRequired && !this._manualPaused && !this._manualStopped &&
      this._lastState.phase !== 'paused';
  }

  _musicLevel() {
    const phase = this._lastState.phase;
    return this.musicVolume * (phase === 'playing' || phase === 'countdown' ? .76 : phase === 'result' ? .38 : .24);
  }

  _sync() {
    if (!this._canPlay()) { this._haltAll(); return; }
    const ctx = this.context, phase = this._lastState.phase;
    this._gain(this._musicBus.gain, this._musicLevel(), .12);
    this._gain(this._sfxBus.gain, this.sfxVolume, 0);
    if (!this._musicSource && this._musicBuffer) {
      const source = ctx.createBufferSource();
      source.buffer = this._musicBuffer;
      source.loop = true;
      source.connect(this._musicBus);
      this._musicStartedAt = ctx.currentTime;
      this._musicStartOffset = this._musicOffset % this._musicBuffer.duration;
      source.start(ctx.currentTime, this._musicStartOffset);
      this._musicSource = source;
    }
    if (!this._ambient) this._ambient = this._waterLoop('ambient', .035, 0);
    const active = new Set();
    if (phase === 'playing') {
      const actors = this._lastState.actors || [];
      const player = actors.find(a => a.isPlayer || a.id === 'p1') || actors[0];
      for (const actor of actors) {
        if (!actor.alive || !actor.shooting || actor.water <= 0) continue;
        const id = actor.id ?? actor.index;
        active.add(id);
        const distance = player ? Math.hypot((actor.x || 0) - (player.x || 0), (actor.y || 0) - (player.y || 0)) : 0;
        const power = Math.max(1, Math.min(2, Number.isFinite(actor.weapon?.visualScale) ? actor.weapon.visualScale : 1));
        const loudness = (actor === player ? .16 : .052 / (1 + distance * .16)) * (1 + (power - 1) * .32);
        const pan = Math.max(-.7, Math.min(.7, (actor.x || 0) / 10));
        if (!this._streams.has(id)) this._streams.set(id, this._waterLoop('spray', loudness, pan));
        const voice = this._streams.get(id);
        this._gain(voice.gain.gain, loudness * (.98 + .04 * Math.sin(ctx.currentTime * 8 + (actor.index || 0))), .055);
        this._gain(voice.filter.frequency, 1450 - (power - 1) * 380, .08);
        if (voice.pan.pan) this._gain(voice.pan.pan, pan, .04);
      }
      if (player?.alive && player.refilling) {
        if (!this._refill) this._refill = this._waterLoop('refill', .06, 0);
      } else if (this._refill) { this._stopLoop(this._refill); this._refill = null; }
    } else if (this._refill) { this._stopLoop(this._refill); this._refill = null; }
    for (const [id, voice] of this._streams) if (!active.has(id)) {
      this._stopLoop(voice); this._streams.delete(id);
    }
  }

  _createWaterNoise() {
    const ctx = this.context, duration = 2.4;
    const buffer = ctx.createBuffer(1, Math.round(duration * ctx.sampleRate), ctx.sampleRate);
    const samples = buffer.getChannelData(0);
    let seed = 0x75ad34, brown = 0, smooth = 0;
    for (let i = 0; i < samples.length; i++) {
      seed ^= seed << 13; seed ^= seed >>> 17; seed ^= seed << 5;
      const white = (seed >>> 0) / 2147483648 - 1;
      brown = (brown + white * .025) / 1.025;
      smooth = smooth * .8 + white * .2;
      const t = i / samples.length;
      const ripple = .76 + .15 * Math.sin(t * Math.PI * 14) + .08 * Math.sin(t * Math.PI * 38);
      samples[i] = (white * .32 + smooth * .8 + brown * 2.8) * ripple;
    }
    // Blend the join so the reusable stream never clicks every 2.4 seconds.
    const n = Math.floor(ctx.sampleRate * .016);
    for (let i = 0; i < n; i++) {
      const p = i / n;
      samples[samples.length - n + i] = samples[samples.length - n + i] * (1-p) + samples[i] * p;
    }
    return buffer;
  }

  _pan(value, destination) {
    const node = this.context.createStereoPanner ? this.context.createStereoPanner() : this.context.createGain();
    if (node.pan) node.pan.value = value;
    node.connect(destination);
    return node;
  }

  _waterLoop(kind, level, pan) {
    const ctx = this.context, source = ctx.createBufferSource(), filter = ctx.createBiquadFilter(), gain = ctx.createGain();
    source.buffer = this._noiseBuffer; source.loop = true;
    filter.type = kind === 'spray' ? 'bandpass' : 'lowpass';
    filter.frequency.value = kind === 'spray' ? 1450 : kind === 'refill' ? 820 : 1900;
    filter.Q.value = kind === 'spray' ? .35 : .4;
    gain.gain.value = level;
    const panner = this._pan(pan, this._sfxBus);
    source.connect(filter); filter.connect(gain); gain.connect(panner);
    source.start(ctx.currentTime, (ctx.currentTime * .731) % this._noiseBuffer.duration);
    return { source, filter, gain, pan: panner };
  }

  _gain(param, value, fade = 0) {
    const t = this.context.currentTime;
    param.cancelScheduledValues?.(t);
    if (fade && param.setTargetAtTime) param.setTargetAtTime(value, t, fade);
    else { param.setValueAtTime?.(value, t); param.value = value; }
  }

  _stopLoop(voice) {
    try { voice.source.stop(); } catch (_) {}
    for (const node of [voice.source, voice.filter, voice.gain, voice.pan]) try { node.disconnect(); } catch (_) {}
  }

  _stopMusic() {
    if (!this._musicSource) return;
    this._musicOffset = (this._musicStartOffset + this.context.currentTime - this._musicStartedAt) % this._musicBuffer.duration;
    try { this._musicSource.stop(); this._musicSource.disconnect(); } catch (_) {}
    this._musicSource = null;
  }

  _haltAll() {
    this._stopMusic();
    if (this._ambient) { this._stopLoop(this._ambient); this._ambient = null; }
    if (this._refill) { this._stopLoop(this._refill); this._refill = null; }
    for (const voice of this._streams.values()) this._stopLoop(voice);
    this._streams.clear();
    for (const voice of this._voices) {
      try { voice.source.stop(); } catch (_) {}
      for (const node of voice.nodes) try { node.disconnect(); } catch (_) {}
    }
    this._voices.clear();
  }

  _oneShotNode(source, duration, level, pan = 0, delay = 0, filterFrequency = null) {
    if (!this._canPlay() || this.sfxVolume === 0) return;
    const ctx = this.context, t = ctx.currentTime + delay, gain = ctx.createGain();
    const nodes = [source, gain];
    let previous = source;
    if (filterFrequency) {
      const filter = ctx.createBiquadFilter(); filter.type = 'lowpass'; filter.frequency.value = filterFrequency;
      previous.connect(filter); previous = filter; nodes.push(filter);
    }
    previous.connect(gain);
    const panner = this._pan(pan, this._sfxBus); nodes.push(panner); gain.connect(panner);
    gain.gain.setValueAtTime(0, t);
    gain.gain.linearRampToValueAtTime(level, t + Math.min(.012, duration * .13));
    gain.gain.exponentialRampToValueAtTime(.0001, t + duration);
    const voice = { source, nodes };
    this._voices.add(voice);
    source.onended = () => {
      for (const node of nodes) try { node.disconnect(); } catch (_) {}
      this._voices.delete(voice);
    };
    while (this._voices.size > 28) {
      const old = this._voices.values().next().value;
      try { old.source.stop(); } catch (_) {}
      for (const node of old.nodes) try { node.disconnect(); } catch (_) {}
      this._voices.delete(old);
    }
    source.start(t); source.stop(t + duration + .025);
  }

  _note(frequency, duration, level, delay = 0, pan = 0, endFrequency = null) {
    if (!this._canPlay()) return;
    const source = this.context.createOscillator(); source.type = 'sine';
    source.frequency.setValueAtTime(frequency, this.context.currentTime + delay);
    if (endFrequency) source.frequency.exponentialRampToValueAtTime(endFrequency, this.context.currentTime + delay + duration);
    this._oneShotNode(source, duration, level, pan, delay);
  }

  _splash(duration, level, pan = 0, cutoff = 2100) {
    if (!this._canPlay()) return;
    const source = this.context.createBufferSource(); source.buffer = this._noiseBuffer;
    this._oneShotNode(source, duration, level, pan, 0, cutoff);
  }

  event(e, state = this._lastState) {
    if (!e || this._disposed) return;
    if (e.type === 'reset') { this._lastEventSeq = 0; return; }
    if (Number.isFinite(e.seq)) {
      if (e.seq <= this._lastEventSeq) return;
      this._lastEventSeq = e.seq;
    }
    if (!this._canPlay()) return;
    const actors = state?.actors || [], actor = actors.find(a => a.id === e.actorId);
    const player = actors.find(a => a.isPlayer || a.id === 'p1') || actors[0];
    const mine = actor === player, pan = Math.max(-.65, Math.min(.65, (e.x ?? actor?.x ?? 0) / 10));
    const now = this.context.currentTime;
    switch (e.type) {
      case 'countdown': {
        const hz = e.value === 1 ? 880 : e.value === 2 ? 740 : 660;
        this._note(hz, .22, .14); this._note(hz * 2, .16, .025); break;
      }
      case 'play':
        [523.25,659.25,783.99,1046.5].forEach((hz,i) => this._note(hz,.36,.075,i*.048)); break;
      case 'shot-start':
        this._splash(.11, mine ? .065 : .018, pan, 1300); break;
      case 'hit':
        if (now - this._lastHitAt < .095) break;
        this._lastHitAt = now;
        this._splash(.12, mine ? .13 : e.sourceId === player?.id ? .095 : .035, pan, 2450);
        if (mine) this._note(150,.10,.08,0,pan,95);
        else if (e.sourceId === player?.id) this._note(570,.08,.045,0,pan,720);
        break;
      case 'elimination':
        this._splash(.6,mine ? .32 : .25,pan,1800);
        this._note(mine ? 340 : 440,.37,.065,0,pan,110);
        this._note(115,.3,.10,.10,pan,76); break;
      case 'refill-start':
        if (mine) [392,523.25,659.25].forEach((hz,i) => this._note(hz,.18,.052,i*.075)); break;
      case 'dry':
        if (mine && now - this._lastDryAt > .65) {
          this._lastDryAt = now; this._note(210,.065,.065,0,0,175); this._note(175,.065,.055,.09,0,145);
        }
        break;
      case 'boss-round':
        if (e.phase !== 'start') break;
        [392,493.88,587.33].forEach((hz,i)=>this._note(hz,.22,.06,i*.09)); break;
      case 'result':
        this.result(e.result?.playerWon ?? e.result?.cleared ?? state.result?.playerWon ?? state.result?.cleared ?? !!player?.alive); break;
    }
  }

  result(playerWon) {
    if (!this._canPlay() || this.context.currentTime - this._lastResultAt < 1.8) return;
    this._lastResultAt = this.context.currentTime;
    const notes = playerWon ? [523.25,659.25,783.99,1046.5] : [523.25,440,349.23,392];
    notes.forEach((hz,i) => this._note(hz,i===3 ? .65 : .27,.11,i*.14));
    if (playerWon) [523.25,659.25,783.99].forEach(hz=>this._note(hz,.65,.06,.42));
  }

  pause() { this._manualPaused = true; this._haltAll(); }
  stop() { this._manualStopped = true; this._haltAll(); }
  dispose() {
    if (this._disposed) return;
    this._disposed = true;
    this._haltAll();
    this._document?.removeEventListener?.('visibilitychange', this._visibility);
    try { const promise = this.context?.close?.(); promise?.catch?.(() => {}); } catch (_) {}
  }

  /** Read-only diagnostics for lifecycle QA; never required by game logic. */
  debugSnapshot() {
    return { enabled: this.enabled, unlocked: this._unlocked, disposed: this._disposed,
      musicPlaying: !!this._musicSource, streamCount: this._streams.size, voiceCount: this._voices.size,
      ambientPlaying: !!this._ambient, refillPlaying: !!this._refill,
      musicOffset: this._musicOffset, musicVolume: this.musicVolume, sfxVolume: this.sfxVolume,
      contextState: this.context?.state || 'not-created', musicDecoded: !!this._musicBuffer,
      decodeFailed: !!this._decodeFailed, error: this._lastError || '',
      foregroundGestureRequired: this._foregroundGestureRequired, masterGain: this._master?.gain.value ?? 0 };
  }
}

// The build embeds the locally composed MP3 below; default music works over file://.
export const BUILTIN_MUSIC_DATA_URI = 'data:audio/mpeg;base64,';
